CREATE TABLE "c_Activity" ("id" BIGINT NOT NULL, "a_Activity_activity_type" TEXT NOT NULL, "a_Activity_occurred_at" TIMESTAMP NOT NULL, "r_ContactActivities_source_id" BIGINT, "r_ContactActivities_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_ContactActivities_source_dtype" IS NULL OR "r_ContactActivities_source_dtype" IN ('Contact','CustomerContact','Lead')), CHECK ((TRUE) OR "r_ContactActivities_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_ContactActivities_source_id" IS NOT NULL));
CREATE TABLE "c_Contact" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Contact_email" TEXT NOT NULL, "r_OrgContacts_source_id" BIGINT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Contact','CustomerContact','Lead')), CHECK ((dtype IN ('Contact','CustomerContact','Lead')) OR "r_OrgContacts_source_id" IS NULL), CHECK (NOT (dtype IN ('Contact','CustomerContact','Lead')) OR "r_OrgContacts_source_id" IS NOT NULL));
CREATE TABLE "c_CustomerContact" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_CustomerContact_customer_since" DATE NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('CustomerContact')));
CREATE TABLE "c_Lead" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Lead_source" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Lead')));
CREATE TABLE "c_Opportunity" ("id" BIGINT NOT NULL, "a_Opportunity_amount" NUMERIC NOT NULL, "a_Opportunity_stage" TEXT NOT NULL, "r_ContactOpportunities_source_id" BIGINT, "r_ContactOpportunities_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_ContactOpportunities_source_dtype" IS NULL OR "r_ContactOpportunities_source_dtype" IN ('Contact','CustomerContact','Lead')), CHECK ((TRUE) OR "r_ContactOpportunities_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_ContactOpportunities_source_id" IS NOT NULL));
CREATE TABLE "c_Organization" ("id" BIGINT NOT NULL, "a_Organization_name" TEXT NOT NULL, PRIMARY KEY ("id"));
ALTER TABLE "c_Activity" ADD CONSTRAINT "fk_c_Activity_0" FOREIGN KEY ("r_ContactActivities_source_id", "r_ContactActivities_source_dtype") REFERENCES "c_Contact" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
